<?php
require_once __DIR__.'/../app/layout.php';$id=(int)($_GET['id']??0);$st=db()->prepare("SELECT j.*,COALESCE(cp.company_name,u.name) company FROM jobs j JOIN users u ON u.id=j.company_id LEFT JOIN company_profiles cp ON cp.user_id=u.id WHERE j.id=? AND j.status='Aktif'");$st->execute([$id]);$j=$st->fetch();if(!$j){http_response_code(404);page_header('Lowongan tidak ditemukan');echo '<section class="section container"><div class="empty"><h1>Lowongan tidak ditemukan</h1><a class="btn btn-primary" href="'.e(url('jobs.php')).'">Kembali</a></div></section>';page_footer();exit;}$already=false;if(current_user()&&current_user()['role']==='candidate'){$a=db()->prepare('SELECT id FROM applications WHERE job_id=? AND candidate_id=?');$a->execute([$id,current_user()['id']]);$already=(bool)$a->fetchColumn();}page_header($j['title'],'jobs'); ?>
<section class="section"><div class="container detail-grid"><div><a class="link" href="<?=e(url('jobs.php'))?>">← Kembali ke lowongan</a><div class="detail-title"><div class="company-logo large"><?=e(initials($j['company']))?></div><div><span class="eyebrow"><?=e($j['employment_type'])?> · <?=e($j['work_type'])?></span><h1><?=e($j['title'])?></h1><p class="muted"><?=e($j['company'])?> · <?=e($j['location'])?></p></div></div><?php foreach(['Tentang pekerjaan'=>'description','Kualifikasi'=>'requirements','Keterampilan'=>'skills','Akomodasi dan aksesibilitas'=>'accessibility'] as $label=>$key):?><div class="detail-block"><h2><?=$label?></h2><?php if($key==='skills'):?><div class="tags"><?php foreach(array_filter(array_map('trim',explode(',',$j[$key]??''))) as $skill):?><span class="tag"><?=e($skill)?></span><?php endforeach;?></div><?php else:?><p class="preserve"><?=e($j[$key]?:($key==='accessibility'?'Hubungi perusahaan untuk mendiskusikan kebutuhan aksesibilitas.':'Belum ada informasi.'))?></p><?php endif;?></div><?php endforeach;?></div><aside class="panel apply-panel"><span class="eyebrow">RINGKASAN LOWONGAN</span><h2><?=e($j['title'])?></h2><?php foreach(['Perusahaan'=>$j['company'],'Lokasi'=>$j['location']?:'Fleksibel','Tipe kerja'=>$j['work_type'],'Gaji'=>$j['salary_range']?:'Sesuai kesepakatan','Batas lamaran'=>$j['deadline']?:'Tidak ditentukan'] as $k=>$v):?><div class="summary"><small><?=e($k)?></small><b><?=e($v)?></b></div><?php endforeach;?><?php if($already):?><div class="alert alert-success">Kamu sudah melamar lowongan ini.</div><a class="btn btn-outline full" href="<?=e(url('candidate/applications.php'))?>">Lihat status lamaran</a><?php elseif(current_user()&&current_user()['role']==='candidate'):?><form method="post" action="<?=e(url('candidate/apply.php'))?>" class="form"><?=csrf_field()?><input type="hidden" name="job_id" value="<?=(int)$j['id']?>"><label>Pesan untuk perekrut (opsional)<textarea name="cover_letter" rows="4" placeholder="Ceritakan ketertarikanmu..."></textarea></label><button class="btn btn-primary full">Kirim lamaran</button></form><?php elseif(!current_user()):?><a class="btn btn-primary full" href="<?=e(url('login.php'))?>">Masuk untuk melamar</a><?php else:?><p class="tiny">Akun perusahaan/admin tidak dapat melamar.</p><?php endif;?><p class="tiny">Informasi akomodasi dapat didiskusikan selama proses rekrutmen.</p></aside></div></section>
<?php page_footer(); ?>
